  const prefersReducedMotion = useReducedMotion();

  const gmail = useGmail();
  const calendar = useGoogleCalendar();
  const whatsapp = useWhatsApp();

  const getToolkitInstance = (toolkit: string) => {
    if (toolkit === "gmail") return gmail;
    if (toolkit === "googlecalendar") return calendar;
    if (toolkit === "whatsapp") return whatsapp;
    return null;
  };

  const items = DEFAULT_DOCK_ITEMS.map((item) => {
    if (item.label === "Integrations") {
      return {
        ...item,
        onClick: () => setShowIntegrations(true),
      };
    }
    return item;
  });

  const handleConnect = async (toolkit: string) => {
    const instance = getToolkitInstance(toolkit);
    if (instance && instance.connect) {
      await instance.connect();
    }
  };

