export function AppDock() {
  const [showIntegrations, setShowIntegrations] = useState(false);
  const prefersReducedMotion = useReducedMotion();
  const [connecting, setConnecting] = useState<string | null>(null);
  const [statuses, setStatuses] = useState<Record<string, "checking" | "connected" | "disconnected">>({});

  const items = DEFAULT_DOCK_ITEMS.map((item) => {
    if (item.label === "Integrations") {
      return {
        ...item,
        onClick: () => setShowIntegrations(true),
      };
    }
    return item;
  });

  const checkStatus = () => {
    setStatuses({ googlecalendar: "checking", gmail: "checking" });

    fetch("/api/composio/connection-status?toolkit=googlecalendar")
      .then(res => res.json())
      .then(data => setStatuses(s => ({ ...s, googlecalendar: data.status })))
      .catch(() => setStatuses(s => ({ ...s, googlecalendar: "disconnected" })));

    fetch("/api/composio/connection-status?toolkit=gmail")
      .then(res => res.json())
      .then(data => setStatuses(s => ({ ...s, gmail: data.status })))
      .catch(() => setStatuses(s => ({ ...s, gmail: "disconnected" })));
  };

  const handleConnect = async (toolkit: string) => {
    try {
      setConnecting(toolkit);
      const res = await fetch("/api/composio/initiate-connection", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ toolkit }),
      });
      const data = await res.json();
      if (data.redirectUrl) {
        window.location.href = data.redirectUrl;
      } else {
        console.error("Failed to get Composio redirect:", data);
        alert(data.error || "Failed to connect to Composio. Check console.");
      }
    } catch (err) {
      console.error(err);
      alert("Failed to connect.");
    } finally {
      setConnecting(null);
    }
  };

